import { model, Schema } from "mongoose";
import {
  VACCINE_LIMITS,
  VaccineAdministrationRoutes,
  VaccineCategories,
  VaccineDosageUnits,
} from "./vaccine.constants.js";
import type { TVaccine } from "./vaccine.interface.js";

const vaccineSchema = new Schema<TVaccine>(
  {
    //generated by generateVaccineCode (VAC-00001) and never accepted from the client
    vaccineCode: {
      type: String,
      required: true,
      unique: true,
      immutable: true,
      trim: true,
      uppercase: true,
    },
    vaccineName: { type: String, required: true, trim: true, maxlength: 150 },
    shortCode: { type: String, required: true, trim: true, uppercase: true, maxlength: 20 },
    //Disease collection (Model 14) is pending; references are validated in the service
    targetDiseaseIds: { type: [{ type: Schema.Types.ObjectId, ref: "Disease" }], default: [] },
    manufacturer: { type: String, trim: true, maxlength: 150 },
    category: { type: String, enum: Object.values(VaccineCategories), required: true },
    dosage: {
      type: Number,
      required: true,
      min: [0.0001, "dosage must be greater than 0"],
      max: VACCINE_LIMITS.maxDosage,
    },
    dosageUnit: { type: String, enum: Object.values(VaccineDosageUnits), required: true },
    administrationRoute: {
      type: String,
      enum: Object.values(VaccineAdministrationRoutes),
      required: true,
    },
    minimumAge: { type: Number, min: 0, max: VACCINE_LIMITS.maxMinimumAgeMonths }, //months
    boosterRequired: { type: Boolean, required: true, default: false },
    boosterAfterDays: { type: Number, min: 1, max: VACCINE_LIMITS.maxIntervalDays },
    repeatIntervalDays: { type: Number, min: 1, max: VACCINE_LIMITS.maxIntervalDays },
    storageTemperature: { type: String, required: true, trim: true, maxlength: 50 },
    description: { type: String, trim: true, maxlength: 2000 },
    isMandatory: { type: Boolean, required: true, default: false },
    //retired instead of deleted so Vaccination / Disease references never break
    isActive: { type: Boolean, required: true, default: true },
  },
  { timestamps: true },
);

//one canonical record per name / short code, case-insensitively
vaccineSchema.index(
  { vaccineName: 1 },
  { unique: true, collation: { locale: "en", strength: 2 } },
);
vaccineSchema.index({ shortCode: 1 }, { unique: true });

//selection screens: active vaccines by category; compliance: mandatory list
vaccineSchema.index({ isActive: 1, category: 1 });
vaccineSchema.index({ isMandatory: 1, isActive: 1 });
vaccineSchema.index({ targetDiseaseIds: 1 });

export const VaccineModel = model<TVaccine>("Vaccine", vaccineSchema);
